// Generated by Cypress Author on 2026-11-24.
// Group the login-error dismissal scenario.
describe('Swag Labs authentication', () => {
  // Define the single scenario for dismissing a login error.
  it('dismisses the empty-login error and stays on the login page', () => {
    // Open the Swag Labs login page.
    cy.visit('/');

    // Submit the login form with both fields empty to trigger an error.
    cy.get('[data-test="login-button"]').click();

    // Confirm the login error is displayed.
    cy.get('[data-test="error"]').should('be.visible');
    // Close the displayed login error.
    cy.get('[data-test="error-button"]').click();

    // Confirm the error container has been removed.
    cy.get('[data-test="error"]').should('not.exist');
    // Confirm the browser remains on the login page.
    cy.location('pathname').should('eq', '/');
  });
});
